def sum_even_numbers(numbers):
    total = 0
    for value in numbers:
        if value % 2 == 0:
            total += value
    return total

def rotate_right(items, k):
    if not items:
        return []
    shift = k % len(items)
    cut = len(items) - shift
    return items[cut:] + items[:cut]

def window_sum(values, start, length):
    low = max(0, start)
    high = min(len(values), start + length)
    if high <= low:
        return 0
    total = 0
    for i in range(low, high):
        total += values[i]
    return total

def max_subarray_sum(numbers):
    if not numbers:
        return 0
    best = numbers[0]
    current = numbers[0]
    for value in numbers[1:]:
        if current + value > value:
            current = current + value
        else:
            current = value
        if current > best:
            best = current
    return best

def most_frequent_word(words):
    counts = {}
    for word in words:
        counts[word] = counts.get(word, 0) + 1
    best = ""
    best_count = 0
    for word in words:
        if counts[word] > best_count:
            best = word
            best_count = counts[word]
    return best

def reverse_word_order(sentence):
    words = sentence.split()
    reversed_words = []
    for i in range(len(words) - 1, -1, -1):
        reversed_words.append(words[i])
    return " ".join(reversed_words)

def flatten(nested):
    result = []
    for item in nested:
        if isinstance(item, list):
            result.extend(flatten(item))
        else:
            result.append(item)
    return result

def two_sum(numbers, target):
    seen = {}
    for j in range(len(numbers)):
        need = target - numbers[j]
        if need in seen:
            return [seen[need], j]
        seen[numbers[j]] = j
    return []

def is_clean_palindrome(text):
    cleaned = [ch.lower() for ch in text if ch.isalnum()]
    low = 0
    high = len(cleaned) - 1
    while low < high:
        if cleaned[low] != cleaned[high]:
            return False
        low += 1
        high -= 1
    return True

def is_balanced(text):
    pairs = {")": "(", "]": "[", "}": "{"}
    stack = []
    for ch in text:
        if ch in "([{":
            stack.append(ch)
        elif ch in pairs:
            if not stack or stack.pop() != pairs[ch]:
                return False
    return len(stack) == 0

class Stack:
    def __init__(self):
        self._items = []

    def push(self, value):
        self._items.append(value)

    def pop(self):
        if not self._items:
            raise IndexError("pop from an empty stack")
        return self._items.pop()

    def peek(self):
        if not self._items:
            raise IndexError("peek at an empty stack")
        return self._items[-1]

    def is_empty(self):
        return len(self._items) == 0


def stack_ops(operations):
    stack = Stack()
    results = []
    for op in operations:
        name = op[0]
        try:
            if name == "push":
                stack.push(op[1])
                results.append(None)
            elif name == "pop":
                results.append(stack.pop())
            elif name == "peek":
                results.append(stack.peek())
            elif name == "is_empty":
                results.append(stack.is_empty())
            else:
                raise ValueError("unknown operation: {}".format(name))
        except IndexError:
            results.append("IndexError")
    return results

import math
from dataclasses import dataclass


@dataclass(frozen=True)
class Point:
    x: float
    y: float

    def distance_to(self, other):
        return math.hypot(self.x - other.x, self.y - other.y)


def point_distance(p1, p2):
    for pair in (p1, p2):
        if pair is None or len(pair) != 2:
            return None
    a = Point(float(p1[0]), float(p1[1]))
    b = Point(float(p2[0]), float(p2[1]))
    return round(a.distance_to(b), 6)

